 function addRoundLabel(parent,text,x,y,z,w=3.1){const c=document.createElement('canvas');c.width=700;c.height=120;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='rgba(9,13,18,.9)';ctx.roundRect(10,10,680,100,26);ctx.fill();ctx.strokeStyle='rgba(232,191,105,.65)';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#f8efdc';ctx.font='600 36px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,350,60);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false}));s.position.set(x,y,z);s.scale.set(w,.56,1);parent.add(s);return s}
