 function room(parent,title,opts={}){const w=opts.w||5.1,d=opts.d||4.0,g=new THREE.Group();roomFloor(g,w,d,opts.floor||0xe3ddcf);wall(g,w,d,opts);if(opts.kind==='meeting')meetingFurniture(g);else if(opts.kind==='analytics')analyticsFurniture(g);else if(opts.kind==='lounge')loungeFurniture(g);else if(opts.kind==='systems')systemsFurniture(g);else workFurniture(g,opts.person);addRoundLabel(g,title,0,2.43,d/2-.05,3.0);parent.add(g);return g}
