 function workFurniture(g,p){desk(g,.7,.2,Math.PI);desk(g,-1.05,-1.12,Math.PI);chair(g,.7,-.55,0);chair(g,-1.05,-1.86,0);plant(g,2,1.3,.9);plant(g,-2,1.15,.8);meshBox(g,.7,.7,.08,0x2a3038,-1.75,1.35,1.82,0,.2,.4);const rb=robot(g,p,.7,-.48,Math.PI);g.userData.robot=rb}
 function meetingFurniture(g){const table=new THREE.Mesh(new THREE.CylinderGeometry(1.28,1.28,.16,48),material(0x8f734c,.05,.5));table.scale.z=.62;table.position.y=.7;g.add(table);for(let i=0;i<6;i++){const a=i/6*Math.PI*2;chair(g,Math.cos(a)*1.68,Math.sin(a)*.94,a+Math.PI/2,0x34383d)}plant(g,2,1.3,.9);plant(g,-2,1.15,.8)}
