 function addRadialWing(scene,angleDeg,title,opts={}){const a=THREE.MathUtils.degToRad(angleDeg),radius=6.9,holder=new THREE.Group();holder.position.set(Math.cos(a)*radius,0,Math.sin(a)*radius);holder.rotation.y=-a+Math.PI/2;room(holder,title,opts);scene.add(holder);return holder}
